# Uses generated FITS/XISF/SER and Windows raster fixtures. .NET Framework 4.8, Windows x64.
param([string]$TestDirectory = (Join-Path $PSScriptRoot 'test-data'), [switch]$TargetsOnly, [switch]$TargetInfoOnly, [switch]$PreviewOnly, [switch]$SkyOnly, [switch]$ExportsOnly, [switch]$ImportsOnly, [switch]$ScanningOnly, [switch]$RemoteOnly, [switch]$AnalyticsOnly)
$ErrorActionPreference = 'Stop'
$compiler = Join-Path $env:WINDIR 'Microsoft.NET\Framework64\v4.0.30319\csc.exe'
$sources = @('Analytics.cs','AnalyticsGraphics.cs','AnalyticsStyle.cs','AnalyticsPortrait.cs','AnalyticsPdf.cs','AnalyticsPreferences.cs','AnalyticsTests.cs','OptimisationTests.cs','EtaEstimate.cs','EtaTests.cs','SecurityTests.cs','ErrorReporting.cs','ArchiveProtection.cs','ArchiveBackup.cs','BackupSets.cs','RepositorySize.cs','BackupSetsTests.cs','ArchiveSafetyTests.cs','ExternalApps.cs','ExternalAppsTests.cs','StackingApps.cs','StackingAppsTests.cs','Model.cs','MountLabels.cs','MountLabelTests.cs','ObservingCities.cs','CityTimeZones.cs','ObservingCityTests.cs','ColumnLayout.cs','CaptureAnnotations.cs','CaptureAnnotationsTests.cs','TargetCards.cs','Localization.cs','LocalizationTests.cs','CatalogNames.cs','TargetNames.cs','TargetNamesTests.cs','InformationMedia.cs','InformationRights.cs','InformationHttp.cs','InformationCache.cs','InformationProviders.cs','InformationCoordinator.cs','OrbitalModel.cs','OrbitalCatalog.cs','HybridInformationTests.cs','TargetInfoCatalog.cs','TargetInfoPresentation.cs','TargetInfoParameters.cs','TargetInfoTests.cs','TableCatalogTests.cs','CaptureGroups.cs','SubframeSessions.cs','MediaFiles.cs','VideoHeaders.cs','VideoTests.cs','CaptureSessions.cs','FilterTests.cs','TargetSelection.cs','CometTargets.cs','CometInfo.cs','TargetWorkflowTests.cs','TargetNavigation.cs','TargetNavigationTests.cs','ImportWorkflow.cs','WorkflowTests.cs','ObservationTargets.cs','Fits.cs','Compatibility.cs','FitsAssets.cs','XisfReader.cs','SerReader.cs','RasterHeaders.cs','MetadataProfiles.cs','MetadataReview.cs','MetadataCompletion.cs','MetadataCompletionTests.cs','MetadataEditing.cs','MetadataEditingTests.cs','CalibrationMatching.cs','AssociatedMetadata.cs','CompatibilityTests.cs','SampledPreview.cs','PreviewData.cs','PreviewCache.cs','Preview.cs','Help.cs','Walkthroughs.cs','Xisf.cs','Classification.cs','StackMetadata.cs','SkyWcs.cs','InstrumentDetection.cs','CelestronOrigin.cs','CelestronOriginTests.cs','CameraDetection.cs','TelescopeConnections.cs','ImportSelection.cs','ImportSelectionTests.cs','AutoUpload.cs','TelescopeRename.cs','FileState.cs','Pipeline.cs','FileTransfer.cs','ImportEngine.cs','ArchiveReset.cs','FileDeletion.cs','Filters.cs','FileSearch.cs','SearchWork.cs','RepositoryOrdering.cs','SearchWorkTests.cs','FileSearchTests.cs','ImportPolicy.cs','ImportPolicyTests.cs','CaptureScreening.cs','DeletionHistory.cs','SourceCleanup.cs','Repository.cs','QualityMetrics.cs','QualityScore.cs','QualityFrames.cs','QualityStore.cs','QualityEngineTests.cs','QualityTests.cs','ScanSupport.cs','SourceHistory.cs','SessionScanCache.cs','FilenameScanCache.cs','FastImportTests.cs','SessionScanTests.cs','StarMatching.cs','PlateSolve.cs','TargetSolving.cs','TargetSolvingTests.cs','EditedExport.cs','Export.cs','ExportTests.cs','AstroBinCsv.cs','AstroBinTests.cs','ExportSummary.cs','DumpInbox.cs','EditedHeaderCache.cs','EditedWorkspace.cs','EditedGallery.cs','EditedDeletion.cs','EditedMetadata.cs','EditedMetadataEditing.cs','EditedTargetMatching.cs','EditedImport.cs','EditedDuplicates.cs','EditedTests.cs','EditedDeletionTests.cs','SirilHandoff.cs','FullResolutionPreview.cs','PreviewResolutionTests.cs','PreviewTests.cs','HelpTests.cs','PreviewGestureTests.cs','SkyContext.cs','Stellarium.cs','TargetOverlay.cs','MoonContext.cs','PlanetEphemeris.cs','PlanetContextTests.cs','Eclipses.cs','EclipseTests.cs','SkyContextTests.cs','StellariumTests.cs','TargetOverlayTests.cs','MoonContextTests.cs','PerformanceTests.cs','TelescopeTests.cs','FailedFilenameTests.cs','ParsingRobustnessTests.cs','Tests.cs','MeteorShowers.cs','MeteorShowersTests.cs','Rotation.cs','CometCatalog.cs') | ForEach-Object { Join-Path $PSScriptRoot $_ }
$sources += @('..\Installer\ConnectivityPolicy.cs','..\Installer\InstallCore.cs','ImportRecovery.cs','RemoteImport.cs','RemoteImportTests.cs','Remote\DownloadCore.cs','Remote\SmbSource.cs','Remote\Discovery.cs') | ForEach-Object { Join-Path $PSScriptRoot $_ }
Copy-Item (Join-Path $PSScriptRoot 'Remote\lib\SMBLibrary.dll') $PSScriptRoot -Force
$informationResources = @("/resource:$PSScriptRoot\..\scripts\orbit-snapshots\1P.json,SbdbFixture.json", "/resource:$PSScriptRoot\InformationMedia.json,InformationMedia.json", "/resource:$PSScriptRoot\InformationProviders.json,InformationProviders.json", "/resource:$PSScriptRoot\OrbitEssentials.json,OrbitEssentials.json", "/resource:$PSScriptRoot\CometCatalog.tsv.gz,CometCatalog.tsv.gz", "/resource:$PSScriptRoot\MeteorShowers.json,MeteorShowers.json")
$languageResources = @(Get-ChildItem -LiteralPath (Join-Path $PSScriptRoot 'Localization') -Filter 'lang-*.txt' | ForEach-Object { "/resource:$($_.FullName),$($_.Name)" })
& $compiler /nologo /target:exe /platform:x64 "/out:$PSScriptRoot\MockAstap.exe" "$PSScriptRoot\MockAstap.cs.txt"
if ($LASTEXITCODE -ne 0) { throw 'Protocol-double compilation failed.' }
& $compiler /nologo /target:exe /platform:x64 /optimize+ "/out:$PSScriptRoot\AstroArchiveTests.exe" "/win32manifest:$PSScriptRoot\app.manifest" "/resource:$PSScriptRoot\catalog.csv,catalog.csv" "/resource:$PSScriptRoot\TargetDescriptions.txt,TargetDescriptions.txt" "/resource:$PSScriptRoot\cities.tsv.gz,cities.tsv.gz" "/resource:$PSScriptRoot\city-timezones.tsv.gz,city-timezones.tsv.gz" "/resource:$PSScriptRoot\sky-constellations.txt,sky-constellations.txt" "/resource:$PSScriptRoot\Quick_Start.txt,Quick_Start.txt" "/r:$PSScriptRoot\Remote\lib\SMBLibrary.dll" /r:System.Web.Extensions.dll /r:System.IO.Compression.dll /r:System.IO.Compression.FileSystem.dll /r:System.Security.dll /r:System.Xml.Linq.dll @languageResources @informationResources @sources
if ($LASTEXITCODE -ne 0) { throw 'Test compilation failed.' }
$runDirectory = Join-Path $TestDirectory ('run-' + [Guid]::NewGuid().ToString('N').Substring(0,12))
$testArguments = @($runDirectory)
if ($AnalyticsOnly) { $testArguments += '--analytics-only' }
if ($TargetInfoOnly) { $testArguments += '--info-only' }
if ($TargetsOnly) { $testArguments += '--targets-only' }
if ($SkyOnly) { $testArguments += '--sky-only' }
if ($PreviewOnly) { $testArguments += '--preview-only' }
if ($ImportsOnly) { $testArguments += '--imports-only' }
if ($ScanningOnly) { $testArguments += '--scanning-only' }
if ($RemoteOnly) { $testArguments += '--remote-only' }
if ($ExportsOnly) { $testArguments += '--exports-only' }
$results = & "$PSScriptRoot\AstroArchiveTests.exe" @testArguments
$testExit = $LASTEXITCODE
$results | Write-Output
if ($testExit -ne 0) { throw 'Tests failed.' }
if ($ExportsOnly -or $SkyOnly -or $TargetInfoOnly -or $AnalyticsOnly -or $TargetsOnly -or $PreviewOnly -or $ImportsOnly -or $ScanningOnly -or $RemoteOnly) { return }

# Separate WIC integration suite, using the same engine with real Windows decoders.
$wpf = Join-Path $env:WINDIR 'Microsoft.NET\Framework64\v4.0.30319\WPF'
$rasterSources = $sources | Where-Object { [IO.Path]::GetFileName($_) -notlike '*Tests.cs' }
$rasterSources += @((Join-Path $PSScriptRoot 'RasterReader.cs'), (Join-Path $PSScriptRoot 'RasterTests.cs'))
& $compiler /nologo /target:exe /platform:x64 /optimize+ "/out:$PSScriptRoot\RasterTests.exe" "/win32manifest:$PSScriptRoot\app.manifest" "/resource:$PSScriptRoot\catalog.csv,catalog.csv" "/resource:$PSScriptRoot\TargetDescriptions.txt,TargetDescriptions.txt" "/resource:$PSScriptRoot\cities.tsv.gz,cities.tsv.gz" "/resource:$PSScriptRoot\city-timezones.tsv.gz,city-timezones.tsv.gz" "/resource:$PSScriptRoot\sky-constellations.txt,sky-constellations.txt" "/r:$PSScriptRoot\Remote\lib\SMBLibrary.dll" /r:System.Web.Extensions.dll /r:System.IO.Compression.dll /r:System.IO.Compression.FileSystem.dll /r:System.Security.dll /r:System.Xml.Linq.dll /r:System.Xaml.dll "/r:$wpf\PresentationCore.dll" "/r:$wpf\WindowsBase.dll" @rasterSources
if ($LASTEXITCODE -ne 0) { throw 'Raster test compilation failed.' }
& "$PSScriptRoot\RasterTests.exe" (Join-Path $runDirectory 'raster')
if ($LASTEXITCODE -ne 0) { throw 'Raster tests failed.' }
